/// Returns the device-resident mesh cache shared by all preview worlds.
pub(crate) fn gpu_mesh_cache(&self) -> SharedGpuMeshCache {
    self.gpu_mesh_cache.clone()
}

/// Returns imported-texture residency shared by every preview renderer.
pub(crate) fn gpu_texture_cache(&self) -> engine::SharedPreviewGpuTextureCache {
    self.gpu_texture_cache.clone()
}

/// Clears only device-owned residency after a render-device replacement.
pub(crate) fn clear_gpu(&self) {
    self.gpu_mesh_cache.clear();
    self.gpu_texture_cache.clear();
    let mut inner = self.lock();
    inner.revision = inner.revision.saturating_add(1);
}

